/// Customer accounts with email and password credentials for authentication,
/// including email verification tracking. Tracks suspension status for
/// account management. Email is the primary authentication identity, with
/// secure password hashing. Customer accounts require email verification
/// before full access to platform features.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer's email address, used for authentication and notifications. Must
  /// be unique across all customers.
  email String

  /// Securely hashed password using bcrypt. Never stored in plaintext.
  password_hash String

  /// Indicates whether customer's email has been verified. Required before
  /// full platform access.
  email_verified Boolean

  /// Indicates whether the customer account is suspended. Suspended accounts
  /// cannot log in.
  is_suspended Boolean

  /// Timestamp when the customer account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the customer account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the customer account was marked for deletion (soft
  /// delete). Never physically deleted from database.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions ecommerce_customer_sessions[]
  emailVerifications ecommerce_customer_email_verifications[]
  passwordResets ecommerce_customer_password_resets[]
  activitySnapshots ecommerce_product_image_snaps[]
  orders ecommerce_orders[]
  refundRequests ecommerce_refund_requests[]
  profile ecommerce_customer_profiles?
  addresses ecommerce_customer_addresses[]
  cartItems ecommerce_cart_items[]

  //----
  // INDEXES
  //----
  @@unique([email])
  @@index([deleted_at])
}

/// Session tokens for customer authentication with JWT access/refresh tokens
/// and 30-minute inactivity timeout. Includes connection metadata for
/// security auditing and session tracking. Each session belongs to a
/// customer and expires after 30 minutes of inactivity.
///
/// The expired_at field enforces 30-minute timeout security constraint,
/// preventing session hijacking. Session data is automatically cleaned up
/// with a background job when expired_at is reached.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_customer_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged customer's {@link ecommerce_customers.id}.
  customer_id String @db.Uuid

  /// Client IP address.
  ip String

  /// Page URL from which the session was initiated.
  href String

  /// Previous page URL that led to session creation.
  referrer String

  /// Timestamp when session was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when session was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when session expires (30 minutes after creation, security
  /// enforcement).
  expired_at DateTime @db.Timestamptz

  /// Timestamp when session was logically deleted (soft delete).
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  customer ecommerce_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@index([customer_id, created_at])
}

