export async function test_api_customer_profile_retrieval(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register customer and authenticate
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "1234",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IEcommerceCustomer.IJoin,
  });
  // 2. Retrieve profile
  const profile =
    await api.functional.ecommerce.customer.profile.at(customerConnection);
  typia.assert(profile);
  // 3. Validate profile
  void TestValidator.predicate(
    "display name present and length between 2-50",
    profile.display_name != null &&
      profile.display_name.length >= 2 &&
      profile.display_name.length <= 50,
  );
  // Check phone number format (should be E.164 format string)
  if (profile.phone_number) {
    TestValidator.predicate(
      "phone number format (E.164)",
      /^\+?[0-9\s\-\(\)]+$/.test(profile.phone_number),
    );
  }
  // Validate customer summary is present
  void TestValidator.equals(
    "customer summary present",
    profile.customer,
    profile.customer,
  );
  // Validate account is active (not suspended)
  void TestValidator.equals(
    "account not suspended",
    profile.customer.isSuspended,
    false,
  );
}

