@Controller("/ecommerce/customer/sessions")
export class EcommerceCustomerSessionsController {
  /**
   * Retrieve customer session records with search capabilities for auditing and security monitoring.
   *
   * This operation enables administrators to filter and view session data for specific customers, providing visibility into user authentication patterns and security events. The endpoint returns a paginated list of session metadata including timestamps of creation and expiration, client IP addresses, navigation paths, and session status.
   *
   * Sessions are automatically managed according to the 30-minute inactivity policy, with their status determined by the expired_at field. This API provides critical insights for security audits and session management by showing historical session activity without compromising the integrity of the immutable session data.
   *
   * The endpoint supports filtering by multiple criteria including customer identifier, IP address, session creation period, and navigation paths, making it suitable for investigating potential security incidents or monitoring user behavior patterns.
   *
   * @param connection
   * @param body Search criteria and pagination parameters for customer session records
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Query ecommerce_customer_sessions table with filtering on customer_id, expired_at, ip, href, and referrer. Apply pagination and sorting based on provided parameters. Exclude sessions marked as deleted (deleted_at is null for active sessions). Return a paginated summary of session records with key metadata including creation timestamp, IP address, and navigation context.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedBody()
    body: IEcommerceCustomerSession.IRequest,
  ): Promise<IPageIEcommerceCustomerSession.ISummary> {
    try {
      return await patchEcommerceCustomerSessions({
        customer,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve detailed session information including security context and navigation history.
   *
   * This endpoint provides full session metadata for auditing and security purposes. The response includes the client's IP address, page URL from which the session was initiated, and previous page URL that led to the session creation. Session expiration automatically occurs 30 minutes after creation per security policy.
   *
   * Active sessions are indicated by the absence of a deletion timestamp; sessions with a deletion timestamp are no longer active but retained for audit purposes. Only customers can view their own session history, while administrators have full access for security monitoring. Session records are maintained in the database until automatically purged by maintenance job.
   *
   * @param connection
   * @param sessionId Unique identifier of the session to retrieve
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification 1. Check session ID format validate as UUID
   * 2. Fetch session record by ID from ecommerce_customer_sessions table
   * 3. Determine session validity:
   *    - If expired_at < current time → return 401
   *    - If deleted_at exists → return 404
   * 4. Return session metadata including IP, href, referrer, created/updated timestamps
   * 5. Apply soft delete check before returning data (deleted_at column exists)
   * 6. Handle session quorum: only allow access to customer owning session or admin role
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":sessionId")
  public async at(
    @CustomerAuth()
    customer: CustomerPayload,
