    sessionId: string & tags.Format<"uuid">,
  ): Promise<IEcommerceCustomerSession> {
    try {
      return await getEcommerceCustomerSessionsSessionId({
        customer,
        sessionId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

