import { Controller } from "@nestjs/common";
import typia, { tags } from "typia";

import { IEcommerceCartItem } from "../../../../api/structures/IEcommerceCartItem";
import { IPageIEcommerceCartItem } from "../../../../api/structures/IPageIEcommerceCartItem";
import { CustomerAuth } from "../../../../decorators/CustomerAuth";
import { CustomerPayload } from "../../../../decorators/payload/CustomerPayload";
import { deleteEcommerceCustomerCartsCartItemId } from "../../../../providers/deleteEcommerceCustomerCartsCartItemId";
import { patchEcommerceCustomerCarts } from "../../../../providers/patchEcommerceCustomerCarts";
import { postEcommerceCustomerCarts } from "../../../../providers/postEcommerceCustomerCarts";
import { putEcommerceCustomerCartsCartItemId } from "../../../../providers/putEcommerceCustomerCartsCartItemId";

@Controller("/ecommerce/customer/carts")
export class EcommerceCustomerCartsController {
  /**
   * Add a product variant to the customer's shopping cart. The system checks inventory availability and combines quantities if the same variant is already in the cart. This operation validates stock levels in real-time to prevent over-additions and updates the cart's subtotal immediately upon successful addition.
   *
   * The endpoint enforces a 300ms inventory check to ensure real-time stock accuracy. When adding a variant that exists in the cart, the system combines the quantities (e.g., 2 items + 3 items = 5 total) and updates the subtotal automatically. Stock validation is required before any addition to prevent adding items with insufficient available quantities.
   *
   * @param connection
   * @param body Product variant details to add to cart
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification 1. Check product variant inventory (quantity > 0) within 300ms
   * 2. If variant exists in cart:
   *    - Combine quantities (new_quantity + existing_quantity)
   *    - Update subtotal based on new quantity
   * 3. If variant doesn't exist in cart:
   *    - Create new cart item entry
   *    - Calculate new subtotal
   * 4. Validate all quantity values against stock limits
   * 5. Return full cart item details upon successful creation
   * 6. Implement in CartService.createCartItem method
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedBody()
    body: IEcommerceCartItem.ICreate,
  ): Promise<IEcommerceCartItem> {
    try {
      return await postEcommerceCustomerCarts({
        customer,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve the current shopping cart items for the authenticated customer.
   *
   * This operation displays all active cart items with product details, variant options, current prices, and quantities. The system validates stock availability for each item and displays warnings when quantities exceed available stock.
   *
   * The response includes item-level subtotals and a total cart value. Paginated results are provided with standard cursor-based pagination for large cart contents.
   *
   * This endpoint requires customer authentication and is intended for UI consumption during the shopping experience.
   *
   * @param connection
   * @param body Filtering and pagination parameters for cart items (currently empty, reserved for future extensions)
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Implement customer cart retrieval operation. Query ecommerce_cart_items table for current customer's active cart items with real-time stock validation. Handle pagination with offset/limit parameters. Include product details from related ecommerce_products and ecommerce_product_variants tables for full item display. Enforce stock quantity validation against ecommerce_variant_inventories. Return summary data for efficient list display.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedBody()
    body: IEcommerceCartItem.IRequest,
  ): Promise<IPageIEcommerceCartItem.ISummary> {
    try {
      return await patchEcommerceCustomerCarts({
        customer,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Update the quantity of a product variant in the customer's shopping cart.
   *
   * This operation allows a customer to adjust the quantity of a specific product variant in their shopping cart. The system will verify that the requested quantity does not exceed available stock levels for the product variant, ensuring accurate cart state and preventing overselling.
   *
   * The operation requires authentication as a customer. The customer must own the cart item (identified by cartItemId) to perform updates. After validation, the cart's total and subtotal are recalculated automatically.
   *
   * Note: Stock levels are checked against the current inventory record in the ecommerce_variant_inventories table. This ensures that inventory is updated in real-time as cart quantities change, maintaining accurate stock management for the product.
   *
   * @param connection
   * @param cartItemId Unique identifier of the cart item to update
   * @param body New quantity for the product variant in the cart
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Query ecommerce_variant_inventories for product_variant_id to validate new quantity against available stock. Update cart item's quantity field with validated new value. Ensure cart item belongs to authenticated customer. Recalculate cart subtotal immediately after update.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Put(":cartItemId")
  public async update(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("cartItemId")
    cartItemId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IEcommerceCartItem.IUpdate,
  ): Promise<IEcommerceCartItem> {
    try {
      return await putEcommerceCustomerCartsCartItemId({
        customer,
        cartItemId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Removes a specific item from the customer's active shopping cart.
   *
   * This operation removes the specified cart item while updating the cart's total value and restoring inventory stock. The system validates that the cart item belongs to the authenticated customer and is not part of any active order. Upon successful deletion, the customer's cart total is updated in real-time and inventory quantities are restored to their pre-cart status.
   *
   * This operation is protected by customer authentication and enforces business rules around cart item lifecycle. Customer must be authenticated to perform this action.
   *
   * Note: The system does not return any response body since the operation only modifies state without providing new data.
   *
   * @param connection
   * @param cartItemId Unique identifier of the cart item to remove
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification 1. Verify cart item exists in ecommerce_cart_items table and belongs to authenticated customer.
   * 2. Check item is not part of any active order to allow removal.
   * 3. Update cart total by subtracting item price * quantity.
   * 4. Increment variant stock quantity in ecommerce_variant_inventories.
   * 5. Log audit record in ecommerce_admin_audit_logs with operation type 'delete_cart_item'.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Delete(":cartItemId")
  public async erase(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("cartItemId")
    cartItemId: string & tags.Format<"uuid">,
  ): Promise<void> {
    try {
      return await deleteEcommerceCustomerCartsCartItemId({
        customer,
        cartItemId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

